(function(){
/* BEGIN EMBEDDED CHECKLIST RULES - generated by build-checklist.cjs */
// Shared by the main-page overview and the scheduled notification backend.
function checklistDay(now = Date.now()) {
    return new Date(now + 8 * 60 * 60 * 1000).toISOString().slice(0, 10);
}
function validChecklistDate(day) {
    if (typeof day !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(day)) return false;
    const time = Date.parse(`${day}T00:00:00Z`);
    return Number.isFinite(time) && new Date(time).toISOString().slice(0, 10) === day;
}
function isChecklistGroupDue(group, day = checklistDay()) {
    if (!validChecklistDate(day)) return false;
    const schedule = group?.schedule;
    if (!schedule || schedule.type === 'daily') return true;
    if (schedule.type === 'once') return validChecklistDate(schedule.date) && day >= schedule.date;
    if (schedule.startDate && (!validChecklistDate(schedule.startDate) || day < schedule.startDate)) return false;
    if (schedule.type === 'interval') {
        const every = Number(schedule.every);
        return validChecklistDate(schedule.startDate) && Number.isInteger(every) && every >= 1 && every <= 3650 &&
            Math.round((Date.parse(`${day}T00:00:00Z`) - Date.parse(`${schedule.startDate}T00:00:00Z`)) / 86400000) % every === 0;
    }
    if (schedule.type === 'weekly') {
        const weekday = new Date(`${day}T00:00:00Z`).getUTCDay();
        return Object.values(schedule.weekdays || {}).some(value => Number(value) === weekday);
    }
    if (schedule.type === 'monthly') {
        const date = Number(schedule.dayOfMonth);
        return Number.isInteger(date) && date >= 1 && date <= 31 && Number(day.slice(8, 10)) === date;
    }
    return false;
}
function checklistScheduleLabel(group) {
    const schedule = group?.schedule;
    if (!schedule || schedule.type === 'daily') return '每天';
    if (schedule.type === 'interval') return `每隔 ${schedule.every} 天 · ${schedule.startDate} 起`;
    if (schedule.type === 'weekly') {
        const days = [...new Set(Object.values(schedule.weekdays || {}).map(Number))].filter(day => Number.isInteger(day) && day >= 0 && day <= 6).sort();
        return `每週${days.map(day => '日一二三四五六'[day]).join('、')}${schedule.startDate ? ` · ${schedule.startDate} 起` : ''}`;
    }
    if (schedule.type === 'monthly') return `每月 ${schedule.dayOfMonth} 號${schedule.startDate ? ` · ${schedule.startDate} 起` : ''}`;
    if (schedule.type === 'once') return `一次性 · ${schedule.date} 起`;
    return '週期設定有誤';
}
function checklistProgress(record, day, once = false) {
    if (!record) return 0;
    if (once && record.byDay && typeof record.byDay === 'object') {
        return Math.max(0, Object.entries(record.byDay).reduce((sum, [date, count]) =>
            sum + (date <= day && Number.isFinite(Number(count)) ? Math.trunc(Number(count)) : 0), 0));
    }
    return typeof record.count === 'number' && Number.isFinite(record.count) ? Math.max(0, Math.floor(record.count)) : record.done ? 1 : 0;
}
function pendingChecklistGroups({ groups = {}, tasks = {}, checks = {}, once = {}, day = checklistDay() } = {}) {
    return Object.entries(groups || {})
        .sort(([a, left], [b, right]) => (Number(left?.order) || 0) - (Number(right?.order) || 0) || a.localeCompare(b))
        .flatMap(([id, group]) => {
            if (!group || typeof group !== 'object' || !isChecklistGroupDue(group, day)) return [];
            const target = Math.max(1, Math.min(99, Math.floor(Number(group.repeatCount) || 1)));
            const items = Object.entries(tasks || {}).filter(([, task]) => task && task.groupId === id && task.enabled !== false);
            const pending = items.filter(([key]) => {
                const isOnce = group.schedule?.type === 'once';
                const record = isOnce ? once?.[id]?.[key] : checks?.[key];
                const count = checklistProgress(record, day, isOnce);
                return count < target;
            }).length;
            return pending ? [{ id, name: typeof group.name === 'string' && group.name.trim() ? group.name.trim() : '未命名分組', pending }] : [];
        });
}
/* END EMBEDDED CHECKLIST RULES */

const state = { groups: {}, tasks: {}, checks: {}, once: {} };
const loaded = { groups: false, tasks: false, checks: false, once: false };
const failed = new Set();
let day = '';
let dayRef, dayHandler;
function render() {
    const box = document.getElementById('pendingOverviewBox');
    if (!box) return;
    box.querySelector('[data-checklist-overview]')?.remove();
    const wrapper = document.createElement('span');
    wrapper.dataset.checklistOverview = 'true';
    wrapper.style.display = 'contents';
    const ready = Object.values(loaded).every(Boolean) && failed.size === 0;
    const groups = ready ? pendingChecklistGroups(state) : [];
    const empty = box.querySelector('[data-rcoin-empty]');
    if (empty) empty.hidden = !ready || groups.length > 0;
    if (!ready) {
        const message = document.createElement('span');
        message.textContent = failed.size ? '📋 Checklist 暫時無法同步' : '📋 Checklist 同步中…';
        message.style.cssText = 'font-size:12px;color:#718096;';
        wrapper.appendChild(message);
    }
    for (const group of groups) {
        const link = document.createElement('a');
        link.className = 'checklist-pending-group';
        link.href = `checklist.html#checklist-group-${encodeURIComponent(group.id)}`;
        link.textContent = `📋 ${group.name}`;
        link.title = '今日 Checklist 未完成分組，點擊開啟清單';
        link.style.cssText = 'display:inline-flex;align-items:center;min-height:32px;padding:4px 10px;border:1px solid #bee3f8;border-radius:8px;background:#ebf8ff;color:#2b6cb0;font-size:13px;font-weight:600;text-decoration:none;overflow-wrap:anywhere;';
        wrapper.appendChild(link);
    }
    box.appendChild(wrapper);
}
document.addEventListener('realfarm-pending-rendered', render);
render();
try {
    const app = firebase.initializeApp({
        apiKey: 'AIzaSyDnEljOXFhS8G7_iI56H_O1IEWofm8HY90',
        authDomain: 'realfarm-checklist.firebaseapp.com',
        databaseURL: 'https://realfarm-checklist-default-rtdb.asia-southeast1.firebasedatabase.app',
        projectId: 'realfarm-checklist',
        appId: '1:307880963686:web:7e2cb68ad9d0a8fab847a7'
    }, 'checklist-overview');
    const root = app.database().ref('daily_checklist');
    const error = field => () => { failed.add(field); render(); };
    for (const field of ['groups', 'tasks', 'once']) {
        root.child(field).on('value', snapshot => {
            state[field] = snapshot.val() || {};
            loaded[field] = true;
            failed.delete(field);
            render();
        }, error(field));
    }
    function bindDay() {
        const next = checklistDay();
        if (next === day) return;
        if (dayRef) dayRef.off('value', dayHandler);
        day = next;
        state.day = day;
        state.checks = {};
        loaded.checks = false;
        render();
        dayRef = root.child(`daily/${day}`);
        const boundDay = day;
        dayHandler = snapshot => {
            if (day !== boundDay) return;
            state.checks = snapshot.val() || {};
            loaded.checks = true;
            failed.delete('checks');
            render();
        };
        dayRef.on('value', dayHandler, error('checks'));
    }
    bindDay();
    setInterval(bindDay, 30000);
    window.addEventListener('focus', bindDay);
    document.addEventListener('visibilitychange', () => { if (!document.hidden) bindDay(); });
} catch {
    failed.add('setup');
    render();
}

})();
